CREATE TABLE IF NOT EXISTS services (id SERIAL PRIMARY KEY, slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL, base_latency_ms INTEGER NOT NULL); CREATE TABLE IF NOT EXISTS checks (id BIGSERIAL PRIMARY KEY, service_id INTEGER REFERENCES services(id), checked_at TIMESTAMPTZ NOT NULL DEFAULT now(), latency_ms INTEGER NOT NULL, ok BOOLEAN NOT NULL, status_code INTEGER NOT NULL); CREATE INDEX IF NOT EXISTS checks_service_time ON checks(service_id, checked_at DESC); CREATE TABLE IF NOT EXISTS incidents (id BIGSERIAL PRIMARY KEY, service_id INTEGER REFERENCES services(id), severity TEXT CHECK(severity IN ('degraded','down')) NOT NULL, cause TEXT NOT NULL, started_at TIMESTAMPTZ NOT NULL DEFAULT now(), resolved_at TIMESTAMPTZ, simulated BOOLEAN NOT NULL DEFAULT false); CREATE UNIQUE INDEX IF NOT EXISTS one_open_incident ON incidents(service_id) WHERE resolved_at IS NULL; INSERT INTO services(slug,name,base_latency_ms) VALUES ('payment-api','Payment API',120),('auth-api','Auth API',60),('orders-api','Orders API',180) ON CONFLICT DO NOTHING; INSERT INTO checks(service_id,checked_at,latency_ms,ok,status_code) SELECT s.id, now() - (g * interval '5 minutes'), round(s.base_latency_ms * (0.8 + random() * 0.4))::int, random() > .02, 200 FROM services s CROSS JOIN generate_series(1,288) g; INSERT INTO incidents(service_id,severity,cause,started_at,resolved_at) SELECT id,'degraded','deploy com rollback',now()-interval '2 days',now()-interval '2 days'+interval '18 minutes' FROM services WHERE slug='payment-api' AND NOT EXISTS (SELECT 1 FROM incidents);
